"""Independently verify completed raw JSONL and recompute the compact-page comparison.

Uses only the standard library, never imports the benchmark driver or its arithmetic,
and launches no JVM. Execute only after the coordinator releases the timing period.
Output is additive and requires a nonexistent destination directory.
"""

from __future__ import annotations

import argparse
from collections import Counter
from fractions import Fraction
import hashlib
import json
import math
from pathlib import Path
import traceback


HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
PROTOCOL_SHA256 = "8ef50b935b83cd22c525616438949f730042ed09c179eff332e39c5601f9b374"
PATCH_SHA256 = "665dca2f8fc662b510fa8d7f285f417a57546e8aec71418f169340c1b8153aa1"
TRANSPORT = "rdf4j.lmdb.resultCoordinateTransport"
ARMS = ("current-off", "current-dense", "compact-dense")
FIXTURES = ("fanout", "shared-tail")
METRICS = ("totalNs", "allThreadAllocatedBytes", "callerThreadAllocatedBytes", "prepareNs",
           "evaluateNs", "firstRowAfterEvaluateNs", "consumeNs", "closeNs", "ledgerPeakBytes")
COMPARISONS = (("compact-dense", "current-dense"), ("compact-dense", "current-off"),
               ("current-dense", "current-off"))


def require(condition, message):
    if not condition:
        raise ValueError(message)


def read_json(path):
    return json.loads(Path(path).read_text())


def sha256(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"))


def median(values):
    ordered = sorted(values)
    require(bool(ordered), "Empty median input")
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2


def write_new(path, value):
    with Path(path).open("x") as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write("\n")


def normalized_metadata(metadata):
    normalized = {k: v for k, v in metadata.items() if k not in ("arm", "source", "store")}
    normalized["jvmArguments"] = [v for v in normalized["jvmArguments"]
                                   if not v.startswith("-D" + TRANSPORT + "=")]
    normalized["systemProperties"] = {k: v for k, v in normalized["systemProperties"].items()
                                      if k != TRANSPORT}
    return normalized


def route_signature(sample):
    counters = sample["counters"]
    return canonical({"selections": sample["successfulSelections"],
                      "compiled": counters["compiledBinds"], "interpreted": counters["interpretedBinds"],
                      "aggregateCompiled": counters["aggregateCompiledBinds"],
                      "aggregateInterpreted": counters["aggregateInterpretedBinds"],
                      "nativeCompiles": counters["semanticNativeCompiles"]})


def bound_runtime_inputs(protocol):
    bindings = {}
    manifests = {}
    pairs = (("classpathFile", "classpathFileSha256"),
             ("classpathManifestFile", "classpathManifestSha256"),
             ("sourceManifestFile", "sourceManifestSha256"),
             ("originalSourceManifestFile", "originalSourceManifestSha256"),
             ("provenanceFile", "provenanceSha256"),
             ("sourceProvenanceFile", "sourceProvenanceSha256"),
             ("productionPatchFile", "productionPatchSha256"),
             ("baseCandidateDescriptorFile", "baseCandidateDescriptorFileSha256"))
    for runtime_name, descriptor in protocol["runtimes"].items():
        checked = {}
        for file_key, hash_key in pairs:
            if file_key in descriptor:
                digest = sha256(descriptor[file_key])
                require(digest == descriptor[hash_key], "Changed frozen input: " + file_key)
                checked[file_key] = {"path": descriptor[file_key], "sha256": digest}
        manifests[runtime_name] = read_json(descriptor["classpathManifestFile"])
        require(len(manifests[runtime_name]) == 128, "Wrong classpath manifest length")
        require(not descriptor.get("diagnosticOnly", False), "Instrumented timing runtime")
        bindings[runtime_name] = checked
    require(all(manifests["original"][i] == manifests["candidate"][i] for i in range(128) if i != 2),
            "A common prefix or original dependency entry differs between arms")
    require(manifests["original"][2]["sha256"] != manifests["candidate"][2]["sha256"],
            "Candidate production bytes do not differ")
    candidate = protocol["runtimes"]["candidate"]
    require(candidate["productionPatchSha256"] == PATCH_SHA256, "Unexpected production patch")
    source_map = read_json(candidate["sourceManifestFile"])
    source_id = "15fe7d5011+followup-source-map-sha256-" + hashlib.sha256(canonical(source_map).encode()).hexdigest()
    require(candidate["productionSourceIdentity"] == source_id, "Candidate source-map identity differs")
    provenance = read_json(candidate["provenanceFile"])
    require(provenance["currentSourcesEqualEverySuccessfulValidation"], "Missing source-matched validation")
    require(provenance["sourceRoleDeltaVersusMeasured"]["production"] == {
        "added": [], "removed": [],
        "changed": ["core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializer.java"]},
        "Unexpected production source change")
    return bindings


def validate_fork(folder, fixture_name, arm, protocol):
    fixture = protocol["fixtures"][fixture_name]
    specification = protocol["armDefinitions"][arm]
    runtime = protocol["runtimes"][specification["runtime"]]
    mode = specification["transportMode"]
    lines = [json.loads(line) for line in (folder / "samples.jsonl").read_text().splitlines() if line.strip()]
    require(len(lines) == 14 and lines[0]["type"] == "metadata", "Incomplete raw fork: " + str(folder))
    metadata, samples = lines[0], lines[1:]
    require(metadata["arm"] == arm and metadata["source"] == runtime["sourceIdentity"], "Wrong source/arm")
    expected_metadata = {**fixture["metadata"], "consumption": "full", "warmup": 8, "measurementsToRun": 5,
                         "nativeEvaluation": True, "directAdjacency": True, "directAdjacencyMode": "PREFER",
                         "valueOverlay": False, "forceSync": False, "indexes": "spoc,ospc,psoc,posc",
                         "globalLedgerLimitBytes": 1073741824, "perQueryLedgerLimitBytes": 268435456,
                         "maxHeapBytes": 1073741824, "javaVersion": "25.0.5+8-LTS",
                         "javaVendor": "Eclipse Adoptium", "namespaceExperimentHarness": "native-and-direct-adjacency-v1"}
    require(all(metadata.get(k) == v for k, v in expected_metadata.items()), "Fixture/JVM metadata changed")
    jvm = protocol["jvmArguments"] + ["-D" + TRANSPORT + "=" + mode]
    require(metadata["jvmArguments"] == jvm, "Wrong JVM arguments")
    require(metadata["systemProperties"] == {"rdf4j.lmdb.hotCounters": "true", TRANSPORT: mode},
            "Unexpected RDF4J property or instrumentation")
    setup = metadata["adjacencySetup"]
    require(setup["state"] == "ACTIVE" and setup["currentRevisionReady"]
            and setup["appliedRevision"] == setup["currentDataRevision"], "Adjacency not ready")
    expected_rows = fixture["metadata"]["expectedRows"]
    expected_checksum = fixture["metadata"]["expectedChecksum"]
    for index, sample in enumerate(samples):
        require(sample["type"] == "sample" and sample["arm"] == arm, "Wrong sample schema/arm")
        require(sample["iteration"] == index - 8 and sample["stage"] == ("warmup" if index < 8 else "measurement"),
                "Query chronology changed")
        require(sample["valid"] and sample["complete"] and sample["rows"] == expected_rows
                and sample["checksum"] == expected_checksum, "Invalid result/checksum")
        require(sample["bindingReads"] == expected_rows * fixture["metadata"]["width"], "Wrong binding read count")
        require(sample["ledgerBeforeBytes"] == sample["ledgerAfterBytes"] == 0 and sample["ledgerReleased"],
                "Unreleased query ledger")
        require(all(type(sample[k]) in (int, float) and math.isfinite(sample[k]) and sample[k] >= 0 for k in METRICS),
                "Invalid timing/allocation/ledger metric")
        if fixture_name == "shared-tail":
            require(all(sample[k] for k in ("exactBagValid", "rowCountValid", "checksumValid", "partialMembershipValid")),
                    "Independent shared-tail bag oracle failed")
        require(sample["autoRequested"] and sample["auto"] and sample["successfulSelections"]
                and sample["omittedSelections"] == 0
                and not any("forced" in route["mode"] for route in sample["successfulSelections"]),
                "AUTO route not observed")
        counters, adjacency = sample["counters"], sample["adjacency"]
        require(counters["semanticNativeCompiles"] == counters["irOpened"] == 1
                and counters["irRows"] == expected_rows, "Native compile/IR participation differs")
        admissions = counters["coordinateAdmissions"]
        require(admissions["opened"] == (0 if mode == "off" else 1)
                and admissions["initialAdmissionRefused"] == admissions["growthAdmissionRefused"] == 0,
                "Coordinate admission differs")
        require(adjacency["stateBefore"] == adjacency["stateAfter"] == "ACTIVE"
                and adjacency["appliedRevisionBefore"] == adjacency["appliedRevisionAfter"]
                == adjacency["currentRevisionBefore"] == adjacency["currentRevisionAfter"] == setup["currentDataRevision"]
                and adjacency["lookupHits"] > 0, "Actual adjacency use/readiness failed")
        if index >= 8:
            require(counters["compiledBinds"] == 1 and counters["interpretedBinds"]
                    == counters["aggregateCompiledBinds"] == counters["aggregateInterpretedBinds"] == 0,
                    "Measured IR tier changed")
    audit = read_json(folder / "root-host-audit.json")
    require(audit["format"] == 1 and audit["type"] == "root-host-audit"
            and audit["harnessMain"] == fixture["harnessMain"] and audit["readPhase"] == fixture["rootReadPhase"]
            and audit["harnessReturned"] and audit["harnessFailureClass"] is None
            and audit["hostedGenericTotal"] == 0 and audit["semanticNativeCompilesTotal"] == 13,
            "Native root audit failed")
    command = read_json(folder / "command.json")
    classpath = Path(runtime["classpathFile"]).read_text().strip()
    expected_argv = [protocol["java"], *jvm, "-cp", classpath, fixture["launcher"], "--arm=" + arm,
                     "--source=" + runtime["sourceIdentity"], "--warmup=8", "--iterations=5", *fixture["arguments"],
                     "--consumption=full", "--output=" + str(folder / "samples.jsonl"), "--store=" + str(folder / "store")]
    require(command["argv"] == expected_argv and command["cwd"] == str(ROOT), "Executed command differs")
    process = read_json(folder / "process-result.json")
    require(process["exitCode"] == 0 and process["failure"] is None, "Fork process failed")
    measured = samples[8:]
    numeric_counters = sorted(k for k, v in measured[0]["counters"].items() if type(v) in (int, float))
    return {"metadata": metadata, "queryCount": 13, "measuredCount": 5,
            "metricSamples": {k: [s[k] for s in measured] for k in METRICS},
            "medians": {k: median([s[k] for s in measured]) for k in METRICS},
            "counterSamples": {k: [s["counters"][k] for s in measured] for k in numeric_counters},
            "counterMedians": {k: median([s["counters"][k] for s in measured]) for k in numeric_counters},
            "routeHistogram": dict(Counter(route_signature(s) for s in measured)),
            "adjacencyLookupHits": [s["adjacency"]["lookupHits"] for s in measured],
            "coldFirstQuery": {k: samples[0][k] for k in METRICS},
            "warmupTiers": [{"iteration": s["iteration"], "compiled": s["counters"]["compiledBinds"],
                             "interpreted": s["counters"]["interpretedBinds"]} for s in samples[:8]],
            "rawInputs": {name: {"path": str(folder / name), "sha256": sha256(folder / name)}
                          for name in ("samples.jsonl", "command.json", "process-result.json", "root-host-audit.json")}}


def recompute(study, protocol):
    forks, indexed, metadata_reference, route_reference = [], {}, {}, {}
    expected_folders = set()
    for round_number, order in enumerate(protocol["balancedOrders"]):
        for fixture_position, fixture in enumerate(protocol["fixtureOrdersByRound"][round_number]):
            for position, arm in enumerate(order):
                folder = study / f"round-{round_number:02d}-{fixture_position:02d}-{fixture}-{position:02d}-{arm}"
                expected_folders.add(folder.name)
                record = validate_fork(folder, fixture, arm, protocol)
                normalized = normalized_metadata(record["metadata"])
                require(normalized == metadata_reference.setdefault(fixture, normalized), "Within-fixture metadata changed")
                signature = record["routeHistogram"]
                require(signature == route_reference.setdefault(fixture, signature), "Within-fixture route histogram changed")
                record.update({"fixture": fixture, "round": round_number, "position": position,
                               "arm": arm, "directory": str(folder)})
                forks.append(record)
                indexed[fixture, round_number, arm] = record
    require({p.name for p in study.glob("round-*") if p.is_dir()} == expected_folders, "Missing or extra study fork")
    require(len(forks) == 36, "Expected exactly 36 JVMs")
    comparisons, lookup = [], {}
    for fixture in FIXTURES:
        for candidate, comparator in COMPARISONS:
            pairs = []
            for round_number in range(6):
                left, right = indexed[fixture, round_number, candidate], indexed[fixture, round_number, comparator]
                require(all(right["medians"][k] > 0 for k in METRICS), "Zero ratio denominator")
                fractions = {k: Fraction(left["medians"][k], right["medians"][k]) for k in METRICS}
                common_counters = sorted(left["counterMedians"].keys() & right["counterMedians"].keys())
                pairs.append({"round": round_number, "ratios": {k: float(v) for k, v in fractions.items()},
                              "metricDifferences": {k: left["medians"][k] - right["medians"][k] for k in METRICS},
                              "counterDifferences": {k: left["counterMedians"][k] - right["counterMedians"][k]
                                                     for k in common_counters},
                              "routeTierHistogramsEqual": left["routeHistogram"] == right["routeHistogram"]})
            summary = {"fixture": fixture, "candidate": candidate, "comparator": comparator, "pairs": pairs,
                       "medianRatios": {k: median([p["ratios"][k] for p in pairs]) for k in METRICS},
                       "ratioRanges": {k: [min(p["ratios"][k] for p in pairs), max(p["ratios"][k] for p in pairs)]
                                       for k in METRICS},
                       "allSixLatencyRatiosFavorCandidate": all(p["ratios"]["totalNs"] < 1 for p in pairs),
                       "allRouteTierHistogramsEqual": all(p["routeTierHistogramsEqual"] for p in pairs)}
            comparisons.append(summary)
            lookup[fixture, candidate, comparator] = summary
    tail = lookup["shared-tail", "compact-dense", "current-dense"]["pairs"]
    gates = {"sharedTailLedgerEveryPairAtMostQuarter": all(p["ratios"]["ledgerPeakBytes"] <= 0.25 for p in tail),
             "sharedTailAllocationEveryPairLower": all(p["ratios"]["allThreadAllocatedBytes"] < 1 for p in tail)}
    for fixture in FIXTURES:
        ratios = [p["ratios"]["totalNs"] for p in lookup[fixture, "compact-dense", "current-dense"]["pairs"]]
        gates[fixture + "MedianLatencyAtMostOne"] = median(ratios) <= 1
        gates[fixture + "EveryLatencyAtMostOnePointTen"] = max(ratios) <= 1.10
    return {"format": 1, "rawValidationPassed": True, "complete": True, "completedJvms": len(forks),
            "rawQueryCount": sum(r["queryCount"] for r in forks),
            "rawMeasuredQueryCount": sum(r["measuredCount"] for r in forks),
            "rawWarmupQueryCount": 36 * 8, "forks": forks, "comparisons": comparisons,
            "engineeringAcceptance": {"passed": all(gates.values()), "gates": gates,
                                       "interpretation": "Prespecified engineering screen, not statistical noninferiority"},
            "method": "Raw JSONL only; all five measurements per JVM, then six within-round median ratios per fixture",
            "runtimeScope": "Frozen descriptor/source/patch files and actual command classpaths checked independently; "
                            "binary tree preservation is additionally supported by the original driver's before/after record",
            "limitations": ["Full consumption only in this timing study", "No cross-fixture pooling",
                            "Adjacency hits include preparation and execution", "Ledger peaks are not heap/RSS",
                            "No explicit closed-owner counter in the uninstrumented timing harness"]}


def compare_driver(result, driver):
    differences = []
    if driver.get("errors") != [] or len(driver.get("comparisons", [])) != 6:
        differences.append("driver errors or comparison count")
    for name in ("complete", "completedJvms", "rawQueryCount", "rawMeasuredQueryCount"):
        if driver.get(name) != result[name]:
            differences.append(name)
    reported = {(c["fixture"], c["candidate"], c["comparator"]): c for c in driver.get("comparisons", [])}
    for computed in result["comparisons"]:
        key = (computed["fixture"], computed["candidate"], computed["comparator"])
        if key not in reported:
            differences.append(str(key) + " missing")
            continue
        other = reported[key]
        for metric in METRICS:
            values = [(computed["medianRatios"][metric], other["medianRatios"][metric])]
            values += list(zip(computed["ratioRanges"][metric], other["ratioRanges"][metric]))
            values += [(a["ratios"][metric], b["ratios"][metric]) for a, b in zip(computed["pairs"], other["pairs"])]
            if len(other["pairs"]) != 6 or not all(math.isclose(a, b, rel_tol=1e-12, abs_tol=1e-12) for a, b in values):
                differences.append(str(key) + ":" + metric)
        for name in ("allSixLatencyRatiosFavorCandidate", "allRouteTierHistogramsEqual"):
            if computed[name] != other[name]:
                differences.append(str(key) + ":" + name)
    if result["engineeringAcceptance"]["passed"] != driver.get("engineeringAcceptance", {}).get("passed"):
        differences.append("engineeringAcceptance.passed")
    gate_names = {
        "shared-tail peak ledger <=25% in every pair": "sharedTailLedgerEveryPairAtMostQuarter",
        "shared-tail all-thread allocation lower in every pair": "sharedTailAllocationEveryPairLower",
        "fanout median paired total latency <=1": "fanoutMedianLatencyAtMostOne",
        "fanout every total latency ratio <=1.10": "fanoutEveryLatencyAtMostOnePointTen",
        "shared-tail median paired total latency <=1": "shared-tailMedianLatencyAtMostOne",
        "shared-tail every total latency ratio <=1.10": "shared-tailEveryLatencyAtMostOnePointTen",
    }
    reported_gates = {gate["name"]: gate["passed"] for gate in driver.get("engineeringAcceptance", {}).get("gates", [])}
    if set(reported_gates) != set(gate_names) or any(
            reported_gates.get(name) != result["engineeringAcceptance"]["gates"][key]
            for name, key in gate_names.items()):
        differences.append("engineeringAcceptance individual gates")
    return {"passed": not differences, "differences": differences,
            "scope": "All six comparisons, nine metrics, six raw paired ratios, medians/ranges and final screen"}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--study", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--protocol", type=Path, default=HERE / "protocol.json")
    args = parser.parse_args()
    study, output = args.study.resolve(strict=True), args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    try:
        require(sha256(args.protocol) == PROTOCOL_SHA256, "Frozen protocol differs from independently reviewed identity")
        require(sha256(study / "used-protocol.json") == PROTOCOL_SHA256, "Study used another protocol")
        protocol = read_json(args.protocol)
        require(protocol["status"] == "frozen-ready" and protocol["arms"] == list(ARMS), "Unexpected protocol arms/status")
        require(protocol["rounds"] == 6 and protocol["warmup"] == 8 and protocol["iterations"] == 5,
                "Unexpected sampling design")
        require(protocol["reviewedProductionPatchSha256"] == PATCH_SHA256, "Wrong reviewed patch")
        bindings = bound_runtime_inputs(protocol)
        for name, descriptor in protocol["runtimes"].items():
            require(read_json(study / "runtime-identities" / name / "runtime-descriptor.json") == descriptor,
                    "Study consumed different runtime descriptor")
        result = recompute(study, protocol)
        preservation = read_json(study / "post-run-preservation.json")
        require(preservation["identityFilesUnchanged"]
                and set(preservation["runtimeIdentitiesUnchanged"]) == {"original", "candidate"}
                and all(preservation["runtimeIdentitiesUnchanged"].values()),
                "Original driver reported post-run identity drift")
        result.update({"study": str(study), "protocolSha256": PROTOCOL_SHA256,
                       "scriptSha256": sha256(Path(__file__)), "boundInputs": bindings,
                       "driverPreservationRecord": preservation})
        result["driverAgreement"] = compare_driver(result, read_json(study / "summary.json"))
        write_new(output / "independent-results.json", result)
        require(result["driverAgreement"]["passed"], "Independent arithmetic disagrees with driver summary")
        print(json.dumps({"output": str(output), "rawValidationPassed": True,
                          "engineeringAcceptance": result["engineeringAcceptance"],
                          "driverAgreement": result["driverAgreement"]}, indent=2))
    except BaseException as failure:
        write_new(output / "failure.json", {"exception": type(failure).__name__, "message": str(failure),
                                             "traceback": traceback.format_exc()})
        raise


if __name__ == "__main__":
    main()
